"""Historical literal bytes, not expectations regenerated by the current renderer."""

import hashlib
from pathlib import Path

import pytest

from hyprmod.core import backups, config, persistence, scoped_config
from hyprmod.core.scopes import Scope

FIXTURES = Path(__file__).parent / "fixtures" / "canonical_v1"
HASHES = {
    "combined": "b9cf20426011f4af74e77ff041a9bbba16cee93046f9924aface55e277fc1bba",
    "empty": "bc75ca71ad89fac9c87dc2c05e4c178638bdc66c8699d694a61ae8d0ea66e4f5",
}


class TestFrozenV1:
    @pytest.mark.parametrize("name", HASHES)
    def test_literal_bytes_and_renderer(self, name):
        raw = (FIXTURES / f"{name}.lua").read_bytes()
        assert hashlib.sha256(raw).hexdigest() == HASHES[name]
        persistence.read_document(raw.decode())
        values = {}
        sections = config.ConfigSections()
        if name == "combined":
            values = {
                "general:gaps_in": "7",
                "decoration:rounding": "12",
                "animations:enabled": "true",
            }
            sections = config.ConfigSections(
                beziers=["bezier = ease, 0.1, 0.2, 0.8, 1"],
                animations=["animation = windows, 1, 5, ease"],
                monitors=[
                    "monitor = DP-1, 2560x1440@144, 0x0, 1",
                    "monitor = HDMI-A-9, disable",
                    "monitor = DP-9, preferred, auto, 1",
                ],
            )
        assert persistence.build_text(values, sections).encode() == raw
        record = scoped_config.read_document(raw.decode())
        assert isinstance(record, scoped_config.LegacyBundle)
        assert record.kind == "legacy-full-bundle"
        assert record.text.encode() == raw
        for scope in Scope:
            with pytest.raises(ValueError, match="conversion review"):
                scoped_config.read_document(raw.decode(), expected_scope=scope)

    @pytest.mark.parametrize("name", HASHES)
    def test_existing_backup_validator_keeps_v1(self, name, tmp_path):
        raw = (FIXTURES / f"{name}.lua").read_bytes()
        directory = tmp_path / "backups"
        directory.mkdir()
        (directory / (HASHES[name] + ".lua")).write_bytes(raw)
        output = tmp_path / "attune.lua"
        output.write_bytes(raw)
        listing = backups.collect_list(output, backup_dir=directory)
        assert len(listing.backups) == 1
        assert listing.backups[0].status == "valid"
        record = scoped_config.read_document(raw.decode())
        assert isinstance(record, scoped_config.LegacyBundle)
